const STOCKS = {
  "jackets": 10,
  "hoodies": 5,
  "mugs": 20,
  "t-shirts": 15
};

const key = query.trim().toLowerCase();

// fuzzy match: does the query contain one of our known item keys?
const matchedKey = Object.keys(STOCKS).find(stockKey => key.includes(stockKey) || stockKey.includes(key));

if (!matchedKey) {
  return `We don't carry '${_query}' — it's not an item in our catalog.`;
}

return `We have ${STOCKS[matchedKey]} of '${query}' in stock.`;

const rawQuery = typeof query === 'string' ? query : (query?.query ?? query?.input ?? JSON.stringify(query));

const ORDERS = {
  "A1234": { status: "shipped", eta: "Tuesday", item: "blue hoodie" },
  "B5678": { status: "processing", eta: "not shipped", item: "red mug" }
};

const orderId = String(rawQuery).trim().toUpperCase();
const order = ORDERS[orderId];

if (!order) {
  return `No order found with ID '${orderId}'. Please double-check the order ID.`;
}

return `Order ${orderId}: status='${order.status}', eta='${order.eta}', item='${order.item}'.`;

const HELP_DOCS = [
  "Returns: items can be returned within 30 days of delivery for a full refund, if unworn with tags attached.",
  "Refunds go to the original payment method and take 5-7 business days after we receive the returned item.",
  "Shipping: standard is 3-5 business days; express is 1-2 days ($12)."
];

return HELP_DOCS.join(" ");

