const ORDERS = {
  "A1234": { status: "shipped", eta: "Tuesday", item: "blue hoodie" },
  "B5678": { status: "processing", eta: "not shipped", item: "red mug" }
};

const orderId = String(rawQuery).trim().toUpperCase();
const order = ORDERS[orderId];

if (!order) {
  return `Cannot refund: no order found with ID '${orderId}'.`;
}

// This return only runs if the human-approval step (on the connector) approved it.
return `Refund approved and processed for order ${orderId} (${order.item}).`;
